param()
$ErrorActionPreference='Stop';$root=$PSScriptRoot;$input=Join-Path $root 'input';$out=Join-Path $root 'outputs';$certDir=Join-Path $out 'certificates';New-Item -ItemType Directory -Force -Path $certDir | Out-Null
Add-Type -AssemblyName System.IO.Compression.FileSystem
function XmlEscape([string]$s){[System.Security.SecurityElement]::Escape($s)}
function Read-DocXml($path){$zip=[IO.Compression.ZipFile]::OpenRead($path);try{$e=$zip.GetEntry('word/document.xml');if($null -eq $e){throw 'Template is missing word/document.xml'};$sr=[IO.StreamReader]::new($e.Open());$x=$sr.ReadToEnd();$sr.Dispose();return $x}finally{$zip.Dispose()}}
function Write-Docx($path,$document){if(Test-Path $path){Remove-Item $path -Force};$e=[ordered]@{};$e['[Content_Types].xml']='<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>';$e['_rels/.rels']='<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>';$e['word/document.xml']=$document; $fs=[IO.File]::Open($path,[IO.FileMode]::Create);$zip=[IO.Compression.ZipArchive]::new($fs,[IO.Compression.ZipArchiveMode]::Create);foreach($key in $e.Keys){$z=$zip.CreateEntry($key);$sw=[IO.StreamWriter]::new($z.Open(),[Text.UTF8Encoding]::new($false));$sw.Write([string]$e[$key]);$sw.Dispose()};$zip.Dispose();$fs.Dispose()}
try{$template=Read-DocXml (Join-Path $input 'CertificateTemplate.docx');$results=@();foreach($s in Import-Csv (Join-Path $input 'students.csv')){$name=XmlEscape $s.StudentName;$course=XmlEscape $s.CourseName;$date=XmlEscape $s.CompletionDate;$doc=$template.Replace('{{STUDENT_NAME}}',$name).Replace('{{COURSE_NAME}}',$course).Replace('{{COMPLETION_DATE}}',$date);$safe=($s.StudentName -replace '[^A-Za-z0-9_-]','_');$file=Join-Path $certDir ($s.StudentId+'_'+$safe+'.docx');Write-Docx $file $doc;$check=Read-DocXml $file;if($check -notmatch [regex]::Escape($name) -or $check.Contains('{{')){throw "Verification failed for $($s.StudentId)"};$results+=[pscustomobject]@{StudentId=$s.StudentId;File=[IO.Path]::GetFileName($file);PersonalizedTextVerified=$true;PdfExport='Not available in portable runtime'}};$results|ConvertTo-Json -Depth 4|Set-Content (Join-Path $out 'verification.json') -Encoding UTF8;Write-Output "Generated and verified $($results.Count) DOCX certificates. PDF export not available."}catch{$_|Out-String|Set-Content (Join-Path $out 'error.log');throw}
